1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: grid; place-items: center;
11	    background: #eef0f3; font-family: system-ui, -apple-system, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 92vw); padding: 16px; border-radius: 16px;
15	    background: #1f2329; box-shadow: 0 10px 30px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 72px; margin-bottom: 12px; padding: 0 12px; border-radius: 10px;
19	    background: #2c323a; color: #fff; font-size: 2.2rem;
20	    display: flex; align-items: center; justify-content: flex-end;
21	    overflow: hidden; white-space: nowrap;
22	  }
23	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
24	  button {
25	    height: 60px; border: 0; border-radius: 10px; font-size: 1.3rem;
26	    background: #3a414b; color: #fff; cursor: pointer;
27	  }
28	  button:active { filter: brightness(1.2); }
29	  .op { background: #f59e0b; }
30	  .clear { background: #6b7280; }
31	  .equals { background: #10b981; }
32	  .wide { grid-column: span 2; }
33	  .tape { margin-top: 12px; padding: 8px 12px; border-radius: 10px; background: #2c323a; color: #fff; }
34	  .tape-head { display: flex; align-items: center; justify-content: space-between; color: #9ca3af; font-size: .85rem; }
35	  .tape-clear { height: auto; padding: 4px 10px; font-size: .85rem; background: #3a414b; }
36	  .tape-list { max-height: 180px; overflow-y: auto; }
37	  .tape-row { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-top: 1px solid #3a414b; }
38	  .tape-row:first-child { border-top: 0; }
39	  .tape-expr { color: #9ca3af; overflow-wrap: anywhere; }
40	  .tape-result { white-space: nowrap; }
41	</style>
42	</head>
43	<body>
44	<div class="calc">
45	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
46	  <div class="keys">
47	    <button class="clear wide" data-testid="key-lparen" data-action="lparen">(</button>
48	    <button class="clear wide" data-testid="key-rparen" data-action="rparen">)</button>
49	    <button class="clear wide" data-testid="key-clear" data-action="clear">AC</button>
50	    <button class="clear" data-testid="key-sign" data-action="sign">±</button>
51	    <button class="op" data-testid="key-div" data-op="/">÷</button>
52	    <button data-testid="key-7" data-digit="7">7</button>
53	    <button data-testid="key-8" data-digit="8">8</button>
54	    <button data-testid="key-9" data-digit="9">9</button>
55	    <button class="op" data-testid="key-mul" data-op="*">×</button>
56	    <button data-testid="key-4" data-digit="4">4</button>
57	    <button data-testid="key-5" data-digit="5">5</button>
58	    <button data-testid="key-6" data-digit="6">6</button>
59	    <button class="op" data-testid="key-sub" data-op="-">−</button>
60	    <button data-testid="key-1" data-digit="1">1</button>
61	    <button data-testid="key-2" data-digit="2">2</button>
62	    <button data-testid="key-3" data-digit="3">3</button>
63	    <button class="op" data-testid="key-add" data-op="+">+</button>
64	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
65	    <button data-testid="key-dot" data-action="dot">.</button>
66	    <button class="equals" data-testid="key-equals" data-action="equals">=</button>
67	  </div>
68	  <div class="tape">
69	    <div class="tape-head">
70	      <span>Tape</span>
71	      <button class="tape-clear" data-testid="tape-clear">Clear</button>
72	    </div>
73	    <div class="tape-list" data-testid="calc-tape"></div>
74	  </div>
75	</div>
76	<script>
77	  // State: acc = stored left operand, op = pending operator,
78	  // entry = digits being typed (string) or null, value = number shown,
79	  // ready = value is a finished right operand made by ± or ), not typed,
80	  // groups = saved { acc, op } of each open parenthesis, innermost last.
81	  // For the tape: expr = committed expression text per group level, innermost
82	  // last; operand = text of the current operand at that level, or null.
83	  var state = { acc: null, op: null, entry: null, value: 0, error: false, ready: false, groups: [], expr: [''], operand: null };
84	  var tape = [];
85	  var SYMBOLS = { '+': '+', '-': '\u2212', '*': '\u00d7', '/': '\u00f7' };
86	
87	  // Expression text of one level plus its operand, without a trailing operator.
88	  function levelText(text, operand) {
89	    if (operand !== null) text += operand.replace(/\.$/, '');
90	    return text.replace(/ \S $/, '');
91	  }
92	
93	  function compute(a, op, b) {
94	    var r;
95	    if (op === '+') r = a + b;
96	    else if (op === '-') r = a - b;
97	    else if (op === '*') r = a * b;
98	    else r = a / b;
99	    if (!isFinite(r)) return NaN;
100	    return r;
101	  }
102	
103	  // Presentation only: stored values are never rounded. At most 10 significant
104	  // digits, no trailing zeros, exponential only for |n| >= 1e10 or < 1e-9.
105	  function formatNumber(n) {
106	    if (n === 0) return '0';
107	    var r = Number(n.toPrecision(10));
108	    var abs = Math.abs(r);
109	    if (abs >= 1e10 || abs < 1e-9) {
110	      return r.toExponential(9).replace(/\.?0+e/, 'e');
111	    }
112	    var exp = Number(r.toExponential(9).split('e')[1]);
113	    var s = r.toFixed(Math.max(0, 9 - exp));
114	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
115	    return s;
116	  }
117	
118	  function pressDigit(d) {
119	    if (state.error) return;
120	    state.ready = false;
121	    if (state.entry === null || state.entry === '0') state.entry = d;
122	    else if (state.entry === '-0') state.entry = '-' + d;
123	    else state.entry += d;
124	    state.value = Number(state.entry);
125	    state.operand = state.entry;
126	  }
127	
128	  function pressDot() {
129	    if (state.error) return;
130	    state.ready = false;
131	    if (state.entry === null) state.entry = '0';
132	    if (state.entry.indexOf('.') === -1) state.entry += '.';
133	    state.value = Number(state.entry);
134	    state.operand = state.entry;
135	  }
136	
137	  // While typing, ± toggles the sign of the typed digits so typing can go on.
138	  // Otherwise it flips the shown value; with an operator waiting, that value
139	  // becomes the right operand (5 + ± = is 0).
140	  function pressSign() {
141	    if (state.error) return;
142	    if (state.entry !== null) {
143	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
144	      state.value = Number(state.entry);
145	      state.operand = state.entry;
146	    } else {
147	      state.value = -state.value;
148	      state.ready = state.op !== null;
149	      if (state.operand === null) state.operand = formatNumber(state.value);
150	      else state.operand = state.operand.charAt(0) === '-' ? state.operand.slice(1) : '-' + state.operand;
151	    }
152	  }
153	
154	  function resolve() {
155	    if (state.op !== null && (state.entry !== null || state.ready)) {
156	      state.value = compute(state.acc, state.op, state.value);
157	      if (isNaN(state.value)) state.error = true;
158	    }
159	  }
160	
161	  // Immediate execution, no precedence: each operator key first finishes the
162	  // waiting operation, strictly left to right, so the display always shows a
163	  // real running result. 2 + 3 × 4 = is 20, not 14.
164	  function pressOp(op) {
165	    if (state.error) return;
166	    resolve();
167	    if (state.error) return;
168	    var top = state.expr.length - 1;
169	    var sym = ' ' + SYMBOLS[op] + ' ';
170	    if (state.operand !== null) state.expr[top] = levelText(state.expr[top], state.operand) + sym;
171	    else if (state.expr[top] !== '') state.expr[top] = state.expr[top].slice(0, -3) + sym;
172	    else state.expr[top] = formatNumber(state.value) + sym;
173	    state.operand = null;
174	    state.acc = state.value;
175	    state.op = op;
176	    state.entry = null;
177	    state.ready = false;
178	  }
179	
180	  // ( saves the waiting operation and starts a fresh one inside the group.
181	  // Inside, the same left-to-right rule applies.
182	  function pressLparen() {
183	    if (state.error) return;
184	    state.groups.push({ acc: state.acc, op: state.op });
185	    state.expr.push('');
186	    state.operand = null;
187	    state.acc = null;
188	    state.op = null;
189	    state.entry = null;
190	    state.value = 0;
191	    state.ready = false;
192	  }
193	
194	  // ) finishes the group; its result becomes the right operand of the saved
195	  // operation (2 + ( 3 × 4 ) = is 14). Ignored with no open group.
196	  function closeGroup() {
197	    resolve();
198	    if (state.error) return;
199	    var g = state.groups.pop();
200	    var inner = levelText(state.expr.pop(), state.operand);
201	    state.operand = '(' + (inner === '' ? formatNumber(state.value) : inner) + ')';
202	    state.acc = g.acc;
203	    state.op = g.op;
204	    state.entry = null;
205	    state.ready = state.op !== null;
206	  }
207	
208	  function pressRparen() {
209	    if (state.error || state.groups.length === 0) return;
210	    closeGroup();
211	  }
212	
213	  // = closes any open groups first.
214	  function pressEquals() {
215	    if (state.error) return;
216	    while (state.groups.length > 0 && !state.error) closeGroup();
217	    if (state.error) return;
218	    resolve();
219	    var text = levelText(state.expr[0], state.operand);
220	    // A calculation is complete when the expression holds at least one operator.
221	    if (!state.error && / [+\u2212\u00d7\u00f7] /.test(text)) tape.unshift({ expr: text, value: state.value });
222	    state.expr = [''];
223	    state.operand = formatNumber(state.value);
224	    state.acc = null;
225	    state.op = null;
226	    state.entry = null;
227	    state.ready = false;
228	  }
229	
230	  function clear() {
231	    state = { acc: null, op: null, entry: null, value: 0, error: false, ready: false, groups: [], expr: [''], operand: null };
232	  }
233	
234	  var display = document.querySelector('[data-testid="calc-display"]');
235	  var tapeList = document.querySelector('[data-testid="calc-tape"]');
236	
237	  function renderTape() {
238	    tapeList.textContent = '';
239	    tape.forEach(function (item) {
240	      var row = document.createElement('div');
241	      row.className = 'tape-row';
242	      row.setAttribute('data-testid', 'tape-row');
243	      var expr = document.createElement('span');
244	      expr.className = 'tape-expr';
245	      expr.setAttribute('data-testid', 'tape-expr');
246	      expr.textContent = item.expr;
247	      var result = document.createElement('span');
248	      result.className = 'tape-result';
249	      result.setAttribute('data-testid', 'tape-result');
250	      result.setAttribute('data-value', String(item.value));
251	      result.textContent = formatNumber(item.value);
252	      row.appendChild(expr);
253	      row.appendChild(result);
254	      tapeList.appendChild(row);
255	    });
256	  }
257	
258	  function render() {
259	    display.setAttribute('data-value', String(state.value));
260	    display.setAttribute('data-error', state.error ? 'true' : 'false');
261	    if (state.error) display.textContent = 'Error';
262	    else display.textContent = state.entry !== null ? state.entry : formatNumber(state.value);
263	  }
264	
265	  document.querySelector('.keys').addEventListener('click', function (e) {
266	    var b = e.target.closest('button');
267	    if (!b) return;
268	    if (b.dataset.digit !== undefined) pressDigit(b.dataset.digit);
269	    else if (b.dataset.op) pressOp(b.dataset.op);
270	    else if (b.dataset.action === 'dot') pressDot();
271	    else if (b.dataset.action === 'sign') pressSign();
272	    else if (b.dataset.action === 'lparen') pressLparen();
273	    else if (b.dataset.action === 'rparen') pressRparen();
274	    else if (b.dataset.action === 'equals') pressEquals();
275	    else if (b.dataset.action === 'clear') clear();
276	    render();
277	    renderTape();
278	  });
279	
280	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
281	    tape = [];
282	    renderTape();
283	  });
284	
285	  render();
286	</script>
287	</body>
288	</html>
